const modern='https://blog.gretschguitars.com/2013/07/gretschtech-understanding-modern-gretsch-serial-numbers/';
const pickups='https://blog.gretschguitars.com/2013/01/gretschtech-picking-the-pickups/';
const bridges='https://blog.gretschguitars.com/2012/07/gretschtech-gretsch-bridges/';
